/* EcoWatt — demo frontend. Datos guardados en localStorage del navegador. */
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const money = n => new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',minimumFractionDigits:2}).format(Number(n)||0);
const num = (n,d=1) => new Intl.NumberFormat('es-PE',{maximumFractionDigits:d}).format(Number(n)||0);
const monthLabel = s => { if(!s)return '—'; const [y,m]=s.split('-'); return new Date(+y,+m-1,1).toLocaleDateString('es-PE',{month:'short',year:'numeric'}).replace('.',''); };
const currentMonth = () => new Date().toISOString().slice(0,7);
const defaultData = () => ({home:{name:'Casa de Jheymi',tariff:0.65,city:'Huaraz, Áncash',solarCapacity:2},bills:[
 {id:1,period:'2026-04',kwh:145,amount:94.25,source:'Manual'},
 {id:2,period:'2026-05',kwh:137,amount:89.05,source:'Manual'},
 {id:3,period:'2026-06',kwh:130,amount:84.50,source:'Manual'}
],goal:{kwh:120,period:currentMonth()},devices:[
 {id:1,name:'Refrigeradora',emoji:'🧊',power:150,hours:8,days:30},
 {id:2,name:'Terma eléctrica',emoji:'🚿',power:1500,hours:1,days:30},
 {id:3,name:'Televisor',emoji:'📺',power:100,hours:5,days:30}
]});
let data = loadData(), currentPage='dashboard', editingId=null, authMode='login', charts={}, liveMap=null, liveMarker=null, locationWatchId=null, lastPosition=null;
function loadData(){try{return JSON.parse(localStorage.getItem('ecowatt-data'))||defaultData()}catch{return defaultData()}}
function saveData(){localStorage.setItem('ecowatt-data',JSON.stringify(data))}
function latest(){return [...data.bills].sort((a,b)=>b.period.localeCompare(a.period))[0]}
function sortedBills(){return [...data.bills].sort((a,b)=>a.period.localeCompare(b.period))}
function cost(b){return b.amount!=null?Number(b.amount):Number(b.kwh)*Number(data.home.tariff)}
function previousTo(b){return sortedBills().filter(x=>x.period<b.period).slice(-1)[0]}
function variation(a,b){if(!b||Number(b)===0)return null;return (a-b)/b*100}
function destroyCharts(){Object.values(charts).forEach(c=>{try{c.destroy()}catch{}});charts={}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function enterApp(email='demo@ecowatt.pe'){ $('#landing').classList.add('hidden');$('#app').classList.remove('hidden');$('#profileEmail').textContent=email;$('#sideHomeName').textContent=data.home.name||'Mi hogar';renderPage('dashboard');window.scrollTo(0,0)}
function leaveApp(){ $('#app').classList.add('hidden');$('#landing').classList.remove('hidden');window.scrollTo(0,0)}
function renderPage(page){
 currentPage=page;destroyCharts();
 $$('.side-link[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 const labels={dashboard:['Panel principal','Tu energía, de un vistazo.'],bills:['Consumo y recibos','Registra y administra tus recibos eléctricos.'],scanner:['Escáner de recibos','Sube una foto o imagen del recibo, revisa los datos extraídos y guárdalos.'],report:['Informe y predicción','Consulta tendencias, escenarios de ahorro y prepara un PDF imprimible.'],history:['Historial y gráficos','Observa cómo evoluciona el consumo de tu hogar.'],compare:['Comparar periodos','Compara dos periodos y encuentra las diferencias.'],goals:['Metas de ahorro','Pequeñas metas para conseguir cambios sostenibles.'],devices:['Electrodomésticos','Registra aparatos y calcula su consumo aproximado.'],deviceAnalysis:['Análisis por aparatos','Explora el consumo estimado, costos y oportunidades de ahorro de cada equipo.'],solar:['EcoWatt GeoSolar','Explora un escenario solar para tu hogar.'],insights:['Recomendaciones inteligentes','Ideas prácticas a partir de los datos registrados.'],settings:['Configuración del hogar','Personaliza los datos utilizados en las estimaciones.'],help:['Ayuda y privacidad','Conoce cómo funciona EcoWatt y cómo se gestionan tus datos.'],location:['Ubicación en tiempo real','Ubica tu dispositivo con permiso y relaciona la zona con tu análisis energético.']};
 $('#breadcrumb').textContent=labels[page][0];$('#pageTitle').innerHTML=(page==='dashboard'?'Hola, '+(data.home.name||'bienvenido')+' <span>✦</span>':labels[page][0]);$('#pageSubtitle').textContent=labels[page][1];
 const renderers={dashboard:dashboardPage,bills:billsPage,scanner:scannerPage,report:reportPage,history:historyPage,compare:comparePage,goals:goalsPage,devices:devicesPage,deviceAnalysis:deviceAnalysisPage,solar:solarPage,insights:insightsPage,settings:settingsPage,help:helpPage,location:locationPage};
 $('#pageContent').innerHTML=(renderers[page]||dashboardPage)();
 bindPageEvents();if(page==='dashboard')drawDashboardCharts();if(page==='deviceAnalysis')drawDeviceAnalysisChart();if(page==='history')drawHistoryCharts();if(page==='location')initLocationPage();
}
function stat(label,value,foot,icon,trend=''){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${trend?`<span class="trend">${trend}</span> `:''}${foot}</div></article>`}
function dashboardPage(){
 const b=latest(),p=previousTo(b),v=p?variation(b.kwh,p.kwh):null,monthlyCost=b?b.kwh*data.home.tariff:0,goal=Number(data.goal.kwh)||0,progress=b&&goal?Math.min(100,b.kwh/goal*100):0;
 return `<section class="welcome-banner"><div><div class="eyebrow"><span class="pulse"></span> RESUMEN ENERGÉTICO</div><h2>Tu hogar, más eficiente.</h2><p>Un pequeño vistazo a cómo estás utilizando la energía.</p></div><button class="btn btn-primary" data-goto="bills">＋ Registrar consumo</button></section>
 <div class="stats-grid">${stat('Último consumo',b?`${num(b.kwh)} <small>kWh</small>`:'—','Periodo '+(b?monthLabel(b.period):'sin datos'),'ϟ',v!==null?(v<=0?`↓ ${num(Math.abs(v))}%`:`↑ ${num(v)}%`):'')}${stat('Costo estimado',b?money(monthlyCost):'—','Basado en tu tarifa actual','S/')}${stat('Tarifa configurada',money(data.home.tariff)+' <small>/ kWh</small>','Tarifa ingresada por ti','⌁')}${stat('Meta mensual',goal?`${num(goal)} <small>kWh</small>`:'Sin meta',`Consumo actual: ${num(progress)}% de la meta`,'◎')}</div>
 <div class="dashboard-grid"><section class="panel-card"><div class="panel-head"><div><h3>Evolución de consumo</h3><p>Consumo eléctrico por periodo</p></div><button class="tiny-btn" data-goto="history">Ver historial ↗</button></div><div class="chart-wrap"><canvas id="dashboardChart"></canvas></div><div class="legend"><span><i></i> Consumo (kWh)</span><span><i class="gold"></i> Gasto estimado (S/)</span></div></section>
 <section class="panel-card"><div class="panel-head"><div><h3>Meta de ahorro</h3><p>Tu objetivo para el periodo actual</p></div><button class="tiny-btn" data-goto="goals">Editar</button></div><div class="goal-ring" style="--progress:${progress}%"><div><b>${num(progress,0)}%</b><small>de la meta</small></div></div><div style="text-align:center;font-size:11px;color:#7d8e80">${b?num(b.kwh)+' kWh registrados':'Registra tu primer recibo'} · Meta ${num(goal)} kWh</div><div class="goal-progress"><span style="width:${progress}%"></span></div><p style="font-size:10px;color:#8b9a8c;text-align:center">${b&&goal?(b.kwh<=goal?'¡Vas dentro de tu meta!':'Necesitas reducir '+num(b.kwh-goal)+' kWh para alcanzar la meta.'):'Configura una meta para comenzar.'}</p></section>
 <section class="panel-card"><div class="panel-head"><div><h3>Últimos registros</h3><p>Tus recibos más recientes</p></div><button class="tiny-btn" data-goto="bills">Ver todos</button></div><div class="activity-list">${[...data.bills].sort((a,b)=>b.period.localeCompare(a.period)).slice(0,4).map(x=>`<div class="activity-row"><span class="activity-icon">▤</span><div><b>${monthLabel(x.period)}</b><small>${x.source||'Registro manual'}</small></div><div style="text-align:right"><strong>${num(x.kwh)} kWh</strong><small>${money(x.kwh*data.home.tariff)}</small></div></div>`).join('')||'<div class="empty-state">Todavía no hay recibos.</div>'}</div></section>
 <section class="panel-card"><div class="panel-head"><div><h3>Tu siguiente paso</h3><p>Una acción simple para hoy</p></div><span class="stat-icon">✦</span></div><div class="recommendation"><div class="rec-icon">☀</div><div><h4>Revisa los equipos de mayor consumo</h4><p>Registra la potencia y las horas de uso para descubrir qué aparatos pueden representar un mayor gasto.</p><small>2 minutos · Impacto potencial</small></div></div><button class="btn btn-dark" data-goto="deviceAnalysis">Abrir análisis por aparatos →</button></section></div>
 <div class="analytics-shortcuts"><section class="panel-card analytics-chart-card"><div class="panel-head"><div><h3>¿Dónde se va la energía?</h3><p>Distribución estimada por electrodoméstico</p></div><button class="tiny-btn" data-goto="deviceAnalysis">Ver análisis ↗</button></div><div class="chart-wrap"><canvas id="dashboardDeviceChart"></canvas></div><div class="mini-insight"><span class="mini-insight-icon">💡</span><span>Registra potencia y horas de uso para que esta distribución sea más representativa de tu hogar.</span></div></section>
 <section class="panel-card analytics-chart-card"><div class="panel-head"><div><h3>Mapa de opciones</h3><p>Elige qué quieres revisar ahora</p></div><span class="stat-icon">✦</span></div><div class="analysis-shortcut-grid"><button data-goto="scanner"><span>🧾</span><b>Escanear recibo</b><small>Leer y revisar datos</small></button><button data-goto="history"><span>📈</span><b>Ver tendencias</b><small>Consumo y costos</small></button><button data-goto="compare"><span>⚖️</span><b>Comparar meses</b><small>Diferencias en kWh y S/</small></button><button data-goto="report"><span>📑</span><b>Informe completo</b><small>Predicción y PDF</small></button></div></section></div>`;
}
function billsPage(){return `<div class="content-heading"><div><h2>Registros de consumo</h2><p>Ingresa los datos de tu recibo de luz.</p></div><button class="btn btn-dark" id="newBillBtn">＋ Nuevo registro</button></div><div class="two-col"><section class="panel-card"><div class="panel-head"><div><h3 id="billFormTitle">${editingId?'Editar registro':'Nuevo recibo'}</h3><p>Los campos con * son obligatorios.</p></div></div><form id="billForm"><div class="field"><label for="billPeriod">Periodo facturado *</label><input type="month" id="billPeriod" required value="${editingId?(data.bills.find(x=>x.id===editingId)||{}).period||currentMonth():currentMonth()}"></div><div class="field"><label for="billKwh">Consumo del recibo (kWh) *</label><input id="billKwh" type="number" min="0" step=".01" placeholder="Ej. 130" required value="${editingId?(data.bills.find(x=>x.id===editingId)||{}).kwh||'':''}"></div><div class="field"><label for="billAmount">Importe total del recibo (S/) — opcional</label><input id="billAmount" type="number" min="0" step=".01" placeholder="Dejar vacío para estimar" value="${editingId?(data.bills.find(x=>x.id===editingId)||{}).amount??'':''}"></div><div class="field"><label for="billSource">Origen del dato</label><select id="billSource"><option>Recibo de luz</option><option>Registro manual</option><option>Estimación</option></select></div><div class="form-actions"><button class="btn btn-dark" type="submit">${editingId?'Guardar cambios':'Guardar registro'}</button><button class="btn btn-light" type="button" id="cancelEdit">Cancelar</button></div></form><div class="notice" style="margin-top:18px;margin-bottom:0">El costo estimado se calcula con kWh × tarifa configurada. El importe total del recibo puede incluir cargos adicionales.</div></section><section class="panel-card"><div class="panel-head"><div><h3>Consejo para registrar</h3><p>Encuentra estos datos en tu recibo.</p></div></div><div class="recommendation"><div class="rec-icon">▤</div><div><h4>Periodo de facturación</h4><p>Usa el mes al que corresponde el consumo. Si tu recibo cubre varios meses, registra el periodo de forma consistente.</p></div></div><div class="recommendation"><div class="rec-icon">ϟ</div><div><h4>Energía consumida</h4><p>Busca el consumo facturado en kWh, no la lectura acumulada del medidor.</p></div></div><div class="recommendation"><div class="rec-icon">S/</div><div><h4>Importe total</h4><p>Si lo ingresas, EcoWatt lo conserva para mostrar el importe real registrado junto al costo energético estimado.</p></div></div></section></div><section class="panel-card" style="margin-top:15px"><div class="panel-head"><div><h3>Historial de recibos</h3><p>${data.bills.length} registros guardados en este navegador</p></div><button class="tiny-btn" id="exportCsv">Exportar CSV ↓</button></div><div class="table-overflow"><table class="data-table"><thead><tr><th>PERIODO</th><th>CONSUMO</th><th>COSTO ESTIMADO</th><th>IMPORTE RECIBO</th><th>CÓDIGO ECO</th><th>ORIGEN</th><th>ACCIONES</th></tr></thead><tbody>${[...data.bills].sort((a,b)=>b.period.localeCompare(a.period)).map(b=>`<tr><td><b>${monthLabel(b.period)}</b></td><td>${num(b.kwh)} kWh</td><td>${money(b.kwh*data.home.tariff)}</td><td>${b.amount!=null?money(b.amount):'—'}</td><td><span class="receipt-code-cell">${escapeHtml(b.receiptCode||'—')}</span></td><td>${escapeHtml(b.source||'Manual')}</td><td><div class="table-actions"><button class="tiny-btn" data-edit="${b.id}">Editar</button><button class="tiny-btn delete" data-delete="${b.id}">Eliminar</button></div></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty-state">No hay registros. Añade tu primer recibo.</div></td></tr>'}</tbody></table></div></section>`}
function scannerPage(){return `<div class="content-heading"><div><h2>Escanea tu recibo de luz</h2><p>Fotografía o selecciona una imagen. EcoWatt intentará leerla en tu navegador.</p></div><span class="scan-code-pill">OCR · lectura asistida</span></div>
 <div class="scan-layout"><section class="panel-card scan-dropzone"><div class="scan-illustration">🧾<span>⚡</span></div><h3>Sube una foto o captura</h3><p>Funciona mejor con el recibo completo, bien iluminado y con texto nítido.</p><label class="btn btn-primary scan-file-label" for="receiptFile">＋ Elegir imagen del recibo</label><input id="receiptFile" type="file" accept="image/*" capture="environment" class="hidden"><div id="scanPreviewWrap" class="scan-preview-wrap hidden"><img id="scanPreview" alt="Vista previa del recibo"><div class="scan-file-meta" id="scanFileMeta"></div></div><button class="btn btn-dark btn-full" id="runOcr" disabled>✧ Leer recibo automáticamente</button><div class="scan-progress hidden" id="scanProgress"><div class="scan-progress-track"><span id="scanProgressBar"></span></div><p id="scanProgressText">Preparando lectura…</p></div><div class="notice" style="margin-top:16px">La lectura automática es una ayuda, no una garantía. Revisa siempre periodo, kWh e importe con el recibo original antes de guardar. El código EW es interno de EcoWatt y no sustituye el código oficial del proveedor eléctrico.</div></section>
 <section class="panel-card"><div class="panel-head"><div><h3>Datos detectados</h3><p>Corrige cualquier dato que no coincida con el recibo.</p></div><span class="scan-code-pill" id="receiptCodeDisplay">Código pendiente</span></div><form id="scanReviewForm"><div class="field"><label for="scanPeriod">Periodo de facturación *</label><input type="month" id="scanPeriod" required value="${currentMonth()}"></div><div class="form-grid"><div class="field"><label for="scanKwh">Consumo (kWh) *</label><input type="number" id="scanKwh" min="0" step=".01" required placeholder="Ej. 130"></div><div class="field"><label for="scanAmount">Importe total (S/)</label><input type="number" id="scanAmount" min="0" step=".01" placeholder="Opcional"></div></div><div class="field"><label for="scanSupplyCode">Código de suministro o recibo (opcional)</label><input id="scanSupplyCode" placeholder="Se completará si se detecta"></div><div class="field"><label for="scanOcrText">Texto reconocido (para revisar)</label><textarea id="scanOcrText" rows="5" placeholder="El texto del recibo aparecerá aquí después de ejecutar la lectura."></textarea></div><div class="form-actions"><button class="btn btn-primary" type="submit">Guardar consumo detectado</button><button class="btn btn-light" type="button" id="scanClear">Limpiar</button></div></form><div id="scanStatus" class="scan-status" role="status">Selecciona una imagen para empezar.</div></section></div>
 <section class="panel-card scan-steps-card"><div class="panel-head"><div><h3>Cómo funciona</h3><p>El proceso conserva el control en tus manos.</p></div></div><div class="scan-steps"><div><b>01</b><span>Sube la imagen</span><small>Foto, PNG o JPG</small></div><div><b>02</b><span>Revisa la lectura</span><small>OCR en el navegador</small></div><div><b>03</b><span>Confirma los datos</span><small>Siempre editable</small></div><div><b>04</b><span>Guarda y analiza</span><small>Historial + PDF</small></div></div></section>`}
function reportPage(){const b=latest(),p=previousTo(b),avg=data.bills.length?data.bills.reduce((s,x)=>s+Number(x.kwh),0)/data.bills.length:0;const pred=forecastKwh();const goal=Number(data.goal.kwh)||0;const potential=b&&goal?Math.max(0,b.kwh-goal)*data.home.tariff:0;const savedVsPrev=b&&p?Math.max(0,p.kwh-b.kwh)*data.home.tariff:0;return `<div class="report-hero"><div><div class="eyebrow">ECOWATT INTELLIGENCE</div><h2>Tu energía en perspectiva</h2><p>Un resumen claro del historial, una proyección básica y oportunidades de ahorro de ${escapeHtml(data.home.name||'tu hogar')}.</p></div><button class="btn btn-primary btn-lg" id="downloadPdfPage">⇩ Generar informe PDF</button></div><div class="stats-grid report-stats">${stat('Último consumo',b?num(b.kwh)+' <small>kWh</small>':'—',b?monthLabel(b.period):'Sin registros','ϟ')}${stat('Costo energético estimado',b?money(b.kwh*data.home.tariff):'—','kWh × tarifa configurada','S/')}${stat('Proyección próximo mes',pred===null?'Faltan datos':num(pred)+' <small>kWh</small>','Promedio de cambios mensuales','↗')}${stat('Ahorro potencial',money(potential),'Si llegas a la meta configurada','✦')}</div>
 <div class="two-col report-grid"><section class="panel-card"><div class="panel-head"><div><h3>Historial de consumo</h3><p>Datos ingresados, no medición en tiempo real.</p></div></div><div class="chart-wrap"><canvas id="reportChart"></canvas></div></section><section class="panel-card"><div class="panel-head"><div><h3>Tu oportunidad de ahorro</h3><p>Escenario estimado frente a la meta.</p></div></div><div class="report-gauge"><div class="report-gauge-ring" style="--report-progress:${b&&goal?Math.min(100,b.kwh/goal*100):0}%"><span>${b&&goal?num(Math.min(100,b.kwh/goal*100),0)+'%':'—'}</span></div><div><b>${goal?num(goal)+' kWh/mes':'Configura una meta'}</b><p>Meta de consumo mensual</p><small>${potential>0?'Podrías reducir aproximadamente '+money(potential)+' al alcanzar tu meta.':'Tu último consumo ya está dentro de la meta, o falta configurar una.'}</small></div></div><div class="notice">${pred===null?'Registra al menos dos periodos para obtener una proyección sencilla.':`La proyección aritmética para el siguiente periodo es ${num(pred)} kWh (aprox. ${money(pred*data.home.tariff)}). No es un pronóstico meteorológico ni un modelo validado.`}</div><p class="report-small-note">${savedVsPrev>0?'Tu consumo bajó frente al periodo anterior: ahorro aproximado de '+money(savedVsPrev)+' a la tarifa configurada.':'El ahorro comparativo solo se calcula si el último periodo registra menos kWh que el anterior.'}</p></section></div>
 <section class="panel-card" style="margin-top:16px"><div class="panel-head"><div><h3>Acciones recomendadas</h3><p>Pasos prácticos basados en tu registro y aparatos configurados.</p></div><button class="tiny-btn" data-goto="insights">Ver recomendaciones ↗</button></div><div class="recommendation"><div class="rec-icon">🚿</div><div><h4>Revisa los aparatos de mayor potencia</h4><p>La terma y otros equipos de alta potencia pueden representar una parte importante del consumo según sus horas de uso.</p></div></div><div class="recommendation"><div class="rec-icon">💡</div><div><h4>Iluminación eficiente</h4><p>Apaga luces en espacios vacíos y aprovecha la luz natural; prioriza focos LED cuando debas reemplazarlos.</p></div></div><div class="recommendation"><div class="rec-icon">🧊</div><div><h4>Cuida la refrigeradora</h4><p>Comprueba el sellado de la puerta y evita abrirla repetidamente durante periodos largos.</p></div></div></section>
 <section class="panel-card" style="margin-top:16px"><div class="panel-head"><div><h3>Detalle de periodos</h3><p>${data.bills.length} registros guardados en este navegador.</p></div><button class="tiny-btn" data-goto="bills">Administrar recibos</button></div><div class="table-overflow"><table class="data-table"><thead><tr><th>Periodo</th><th>Consumo</th><th>Costo estimado</th><th>Importe recibo</th><th>Origen</th></tr></thead><tbody>${sortedBills().slice().reverse().map(x=>`<tr><td>${monthLabel(x.period)}</td><td>${num(x.kwh)} kWh</td><td>${money(x.kwh*data.home.tariff)}</td><td>${x.amount==null?'—':money(x.amount)}</td><td>${escapeHtml(x.source||'Manual')}</td></tr>`).join('')||'<tr><td colspan="5">Todavía no hay registros.</td></tr>'}</tbody></table></div></section>`}
function forecastKwh(){const arr=sortedBills();if(arr.length<2)return null;const diffs=[];for(let i=1;i<arr.length;i++)diffs.push(Number(arr[i].kwh)-Number(arr[i-1].kwh));const avgDiff=diffs.reduce((s,n)=>s+n,0)/diffs.length;return Math.max(0,Number(arr[arr.length-1].kwh)+avgDiff)}
function generateReceiptCode(){return 'EW-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+Math.random().toString(36).slice(2,8).toUpperCase()}
function runReceiptOcr(file){const status=$('#scanStatus'),progress=$('#scanProgress'),bar=$('#scanProgressBar'),txt=$('#scanProgressText');if(!file)return;if(!window.Tesseract){status.textContent='No se pudo cargar el módulo OCR. Revisa tu conexión o ingresa los datos manualmente.';return}progress.classList.remove('hidden');status.textContent='Leyendo la imagen…';$('#runOcr').disabled=true;Tesseract.recognize(file,'spa+eng',{logger:m=>{if(m.status==='recognizing text'){bar.style.width=Math.round((m.progress||0)*100)+'%';txt.textContent=`Reconociendo texto: ${Math.round((m.progress||0)*100)}%`}}}).then(({data:{text}})=>{const raw=text||'';$('#scanOcrText').value=raw;const kwhMatches=[...raw.matchAll(/(?:consumo|energ[ií]a|total\s+activa|kwh)[^\d]{0,30}(\d{1,5}(?:[.,]\d{1,3})?)/ig)].map(m=>m[1]);let kwh=null;for(const m of kwhMatches){const n=Number(m.replace(',','.'));if(n>0&&n<100000){kwh=n;break}}if(kwh!==null)$('#scanKwh').value=kwh;const moneyMatches=[...raw.matchAll(/(?:total\s+a\s+pagar|importe\s+total|total\s+recibo|monto\s+total)[^\d]{0,25}(\d{1,5}(?:[.,]\d{2})?)/ig)].map(m=>m[1]);if(moneyMatches.length){const val=Number(moneyMatches[0].replace(',','.'));if(val>0)$('#scanAmount').value=val}const monthMatch=raw.match(/(?:periodo|per[ií]odo|mes\s+de\s+facturaci[oó]n)[^\n]{0,35}(0?[1-9]|1[0-2])[\/\-. ](20\d{2})/i);if(monthMatch){const mm=String(monthMatch[1]).padStart(2,'0');$('#scanPeriod').value=`${monthMatch[2]}-${mm}`}const code=raw.match(/(?:suministro|cliente|recibo|contrato)[^A-Z0-9]{0,15}([A-Z0-9-]{5,20})/i);if(code)$('#scanSupplyCode').value=code[1];const receiptCode=$('#receiptCodeDisplay').dataset.code||generateReceiptCode();$('#receiptCodeDisplay').textContent=receiptCode;$('#receiptCodeDisplay').dataset.code=receiptCode;status.textContent=kwh!==null?'Lectura terminada. Verifica los campos resaltados con tu recibo original.':'Se reconoció el texto, pero no se identificó con seguridad el consumo. Completa los campos manualmente.';toast('Lectura OCR terminada; verifica los datos.');}).catch(err=>{console.error(err);status.textContent='No se pudo leer esta imagen. Prueba con una foto más nítida o ingresa los datos manualmente.'}).finally(()=>{$('#runOcr').disabled=false;progress.classList.add('hidden')})}
function downloadPdfReport(){if(!window.jspdf?.jsPDF){toast('No se pudo cargar el generador PDF. Revisa tu conexión a internet.');return}const {jsPDF}=window.jspdf;const doc=new jsPDF({unit:'mm',format:'a4'});const b=latest(),prev=previousTo(b),goal=Number(data.goal.kwh)||0,avg=data.bills.length?data.bills.reduce((s,x)=>s+x.kwh,0)/data.bills.length:0,pred=forecastKwh();const savingGoal=b&&goal?Math.max(0,b.kwh-goal)*data.home.tariff:0;const savedPrev=b&&prev?Math.max(0,prev.kwh-b.kwh)*data.home.tariff:0;const pageW=210,margin=16;let y=18;doc.setFillColor(8,39,28);doc.rect(0,0,pageW,43,'F');doc.setTextColor(213,243,106);doc.setFont('helvetica','bold');doc.setFontSize(23);doc.text('EcoWatt',margin,19);doc.setTextColor(255,255,255);doc.setFontSize(11);doc.text('INFORME DE ANALISIS ENERGETICO',margin,29);doc.setFontSize(9);doc.text(`${data.home.name||'Mi hogar'} · ${data.home.city||'Ubicación no configurada'}`,margin,37);doc.setTextColor(25,67,43);y=55;doc.setFontSize(15);doc.setFont('helvetica','bold');doc.text('Resumen del hogar',margin,y);y+=8;doc.setFontSize(9);doc.setFont('helvetica','normal');const rows=[['Periodo más reciente',b?monthLabel(b.period):'Sin registros'],['Código EcoWatt del recibo',b&&b.receiptCode?b.receiptCode:'No generado / registro manual'],['Código de suministro',b&&b.supplyCode?b.supplyCode:'No ingresado'],['Consumo registrado',b?`${num(b.kwh)} kWh`:'—'],['Tarifa configurada',`${money(data.home.tariff)} por kWh`],['Costo energético estimado',b?money(b.kwh*data.home.tariff):'—'],['Importe total del recibo',b&&b.amount!=null?money(b.amount):'No ingresado'],['Meta mensual',goal?`${num(goal)} kWh`:'No configurada'],['Ahorro potencial al alcanzar la meta',money(savingGoal)],['Ahorro comparado con el periodo anterior',money(savedPrev)],['Promedio histórico',data.bills.length?`${num(avg)} kWh por periodo`:'Sin datos'],['Proyección básica próximo periodo',pred===null?'Se requieren al menos 2 periodos':`${num(pred)} kWh · aprox. ${money(pred*data.home.tariff)}`]];rows.forEach((r,i)=>{doc.setFillColor(i%2?239:247,i%2?249:252,i%2?240:232);doc.roundedRect(margin,y-4,pageW-margin*2,8,1.5,1.5,'F');doc.setTextColor(58,90,68);doc.text(r[0],margin+3,y+1);doc.setTextColor(20,57,39);doc.setFont('helvetica','bold');doc.text(String(r[1]),pageW-margin-3,y+1,{align:'right',maxWidth:100});doc.setFont('helvetica','normal');y+=9});y+=5;doc.setFont('helvetica','bold');doc.setFontSize(13);doc.setTextColor(25,67,43);doc.text('Historial de consumo',margin,y);y+=7;const arr=sortedBills().slice(-8);if(arr.length){const max=Math.max(...arr.map(x=>x.kwh),1),chartX=margin,chartY=y,chartW=pageW-margin*2,barGap=5,barW=(chartW-(arr.length-1)*barGap)/arr.length;arr.forEach((x,i)=>{const h=(x.kwh/max)*27;const xx=chartX+i*(barW+barGap);doc.setFillColor(i===arr.length-1?45:82,i===arr.length-1?174:196,i===arr.length-1?99:118);doc.roundedRect(xx,chartY+29-h,barW,h,1.2,1.2,'F');doc.setFontSize(7);doc.setTextColor(66,97,75);doc.text(monthLabel(x.period).replace(/\s/g,' '),xx+barW/2,chartY+34,{align:'center',maxWidth:barW+3});doc.setFontSize(7);doc.text(String(Math.round(x.kwh)),xx+barW/2,chartY+26-h,{align:'center'})});y+=44}else{doc.setFont('helvetica','normal');doc.setFontSize(9);doc.text('Aún no hay registros de consumo.',margin,y);y+=8}doc.setFont('helvetica','bold');doc.setFontSize(12);doc.text('Registros detallados',margin,y);y+=7;doc.setFontSize(8);doc.setFillColor(8,55,37);doc.rect(margin,y-4,pageW-margin*2,7,'F');doc.setTextColor(255,255,255);doc.text('Periodo',margin+2,y);doc.text('kWh',82,y);doc.text('Costo est.',111,y);doc.text('Importe recibo',146,y);doc.text('Origen',pageW-margin-2,y,{align:'right'});y+=7;doc.setTextColor(35,68,48);doc.setFont('helvetica','normal');arr.forEach((x,i)=>{if(y>270){doc.addPage();y=20}if(i%2===0){doc.setFillColor(241,248,238);doc.rect(margin,y-4,pageW-margin*2,7,'F')}doc.text(monthLabel(x.period),margin+2,y);doc.text(`${num(x.kwh)} kWh`,82,y);doc.text(money(x.kwh*data.home.tariff),111,y);doc.text(x.amount==null?'—':money(x.amount),146,y);doc.text(String(x.source||'Manual').slice(0,16),pageW-margin-2,y,{align:'right'});y+=7});doc.addPage();y=20;doc.setFillColor(8,39,28);doc.rect(0,0,pageW,28,'F');doc.setTextColor(213,243,106);doc.setFont('helvetica','bold');doc.setFontSize(18);doc.text('Ahorro, equipos y recomendaciones',margin,17);y=40;doc.setTextColor(25,67,43);doc.setFontSize(12);doc.text('Consumo estimado de aparatos registrados',margin,y);y+=8;doc.setFont('helvetica','normal');doc.setFontSize(9);if(data.devices.length){data.devices.forEach(d=>{const kwh=d.power/1000*d.hours*d.days;doc.setTextColor(35,68,48);doc.text(`${d.name} · ${d.power} W · ${d.hours} h/día`,margin,y);doc.text(`${num(kwh)} kWh/mes · ${money(kwh*data.home.tariff)}`,pageW-margin,y,{align:'right'});y+=7})}else{doc.text('No hay aparatos registrados.',margin,y);y+=7}y+=8;doc.setFont('helvetica','bold');doc.setFontSize(12);doc.text('Recomendaciones prácticas',margin,y);y+=8;doc.setFont('helvetica','normal');doc.setFontSize(9);const tips=['Revisa las horas de uso de los equipos de mayor potencia, especialmente la terma eléctrica.','Aprovecha la luz natural y apaga la iluminación en habitaciones vacías.','Evita mantener cargadores y equipos encendidos cuando no los necesitas.','Compara cada recibo mensual para identificar cambios y comprobar si los hábitos ayudan.','Verifica sellos de puertas y ventilación de la refrigeradora.'];tips.forEach((t,i)=>{const lines=doc.splitTextToSize(`${i+1}. ${t}`,pageW-margin*2-4);doc.text(lines,margin+2,y);y+=lines.length*5+3});y+=5;doc.setFillColor(229,247,218);doc.roundedRect(margin,y,pageW-margin*2,27,3,3,'F');doc.setTextColor(28,88,54);doc.setFont('helvetica','bold');doc.text('Importante',margin+4,y+7);doc.setFont('helvetica','normal');doc.setFontSize(8);doc.text(doc.splitTextToSize('Los costos y proyecciones son estimaciones basadas en los datos ingresados. No sustituyen el recibo oficial, una medición eléctrica ni una predicción validada. La reducción posible depende de los hábitos, equipos y tarifa reales.',pageW-margin*2-8),margin+4,y+13);doc.setFontSize(8);doc.setTextColor(100,120,105);doc.text(`Generado por EcoWatt · ${new Date().toLocaleString('es-PE')}`,margin,286);doc.save(`EcoWatt-informe-${new Date().toISOString().slice(0,10)}.pdf`);toast('Informe PDF generado.')}
function historyPage(){return `<div class="content-heading"><div><h2>Tu consumo a través del tiempo</h2><p>Gráficos basados en los recibos que has registrado.</p></div><button class="btn btn-dark" data-goto="bills">＋ Añadir recibo</button></div><div class="dashboard-grid"><section class="panel-card"><div class="panel-head"><div><h3>Consumo por periodo</h3><p>kWh registrados</p></div></div><div class="chart-wrap"><canvas id="historyConsumption"></canvas></div></section><section class="panel-card"><div class="panel-head"><div><h3>Gasto energético estimado</h3><p>Soles peruanos (S/)</p></div></div><div class="chart-wrap"><canvas id="historyCost"></canvas></div></section></div><section class="panel-card" style="margin-top:14px"><div class="panel-head"><div><h3>Resumen histórico</h3><p>Estadísticas de los registros disponibles</p></div></div><div class="stats-grid">${stat('Periodos registrados',data.bills.length,'Recibos en el historial','▤')}${stat('Consumo acumulado',num(data.bills.reduce((s,b)=>s+Number(b.kwh),0))+' <small>kWh</small>','Suma de registros','ϟ')}${stat('Promedio por periodo',data.bills.length?num(data.bills.reduce((s,b)=>s+Number(b.kwh),0)/data.bills.length)+' <small>kWh</small>':'—','Promedio simple','⌁')}${stat('Gasto estimado acumulado',money(data.bills.reduce((s,b)=>s+b.kwh*data.home.tariff,0)),'Según tarifa actual','S/')}</div></section>`}
function comparePage(){const bills=sortedBills();const a=bills[bills.length-2],b=bills[bills.length-1];return `<div class="content-heading"><div><h2>Dos periodos, una perspectiva</h2><p>Selecciona meses para comparar sus consumos y costos.</p></div></div><section class="panel-card"><div class="form-grid"><div class="field"><label>Periodo A</label><select id="compareA">${bills.map(x=>`<option value="${x.id}" ${a&&x.id===a.id?'selected':''}>${monthLabel(x.period)} · ${num(x.kwh)} kWh</option>`).join('')}</select></div><div class="field"><label>Periodo B</label><select id="compareB">${bills.map(x=>`<option value="${x.id}" ${b&&x.id===b.id?'selected':''}>${monthLabel(x.period)} · ${num(x.kwh)} kWh</option>`).join('')}</select></div></div><div id="compareResults">${compareResult(a,b)}</div></section><section class="panel-card" style="margin-top:14px"><div class="panel-head"><div><h3>Cómo leer la comparación</h3><p>Una referencia para interpretar el cambio.</p></div></div><div class="recommendation"><div class="rec-icon">↓</div><div><h4>Una diferencia negativa puede ser positiva</h4><p>Si el periodo más reciente registra menos kWh, puede reflejar hábitos más eficientes, clima distinto o cambios en el uso de equipos. Comprueba el contexto antes de concluir.</p></div></div><div class="notice">Si el periodo de referencia tiene 0 kWh, el porcentaje no se calcula para evitar una división entre cero.</div></section>`}
function compareResult(a,b){if(!a||!b)return '<div class="empty-state">Registra al menos dos periodos para compararlos.</div>';const dk=Number(b.kwh)-Number(a.kwh),dc=(b.kwh-a.kwh)*data.home.tariff,pct=variation(b.kwh,a.kwh);return `<div class="compare-result"><div><small>DIFERENCIA DE CONSUMO</small><b style="color:${dk<=0?'#399d51':'#c17b35'}">${dk>0?'+':''}${num(dk)} kWh</b></div><div><small>DIFERENCIA DE COSTO ESTIMADO</small><b style="color:${dc<=0?'#399d51':'#c17b35'}">${dc>0?'+':''}${money(dc)}</b></div><div><small>VARIACIÓN PORCENTUAL</small><b>${pct===null?'No disponible':`${pct>0?'+':''}${num(pct)}%`}</b></div></div><p style="font-size:11px;color:#7f9083;margin-top:18px">${monthLabel(a.period)}: ${num(a.kwh)} kWh · ${monthLabel(b.period)}: ${num(b.kwh)} kWh. ${dk<0?'El consumo disminuyó.':dk>0?'El consumo aumentó.':'El consumo se mantuvo igual.'}</p>`}
function goalsPage(){const b=latest(),goal=Number(data.goal.kwh)||0,progress=b&&goal?Math.min(100,b.kwh/goal*100):0;return `<div class="content-heading"><div><h2>Una meta a tu medida</h2><p>Establece un objetivo mensual de consumo eléctrico.</p></div></div><div class="two-col"><section class="panel-card"><div class="panel-head"><div><h3>Tu meta mensual</h3><p>Define el consumo que deseas alcanzar.</p></div></div><form id="goalForm"><div class="field"><label for="goalKwh">Meta de consumo (kWh/mes)</label><input type="number" id="goalKwh" min="1" step="1" value="${goal||120}" required></div><div class="field"><label for="goalPeriod">Periodo objetivo</label><input type="month" id="goalPeriod" value="${data.goal.period||currentMonth()}" required></div><button class="btn btn-dark" type="submit">Guardar meta</button></form></section><section class="panel-card"><div class="panel-head"><div><h3>Avance actual</h3><p>Comparado con el último recibo registrado.</p></div></div><div class="goal-ring" style="--progress:${progress}%"><div><b>${num(progress,0)}%</b><small>de la meta</small></div></div><div style="text-align:center"><b>${b?num(b.kwh)+' kWh':'Sin datos'}</b><p style="font-size:10px;color:#819184">Meta: ${num(goal)} kWh</p><div class="goal-progress"><span style="width:${progress}%"></span></div><p style="font-size:11px;color:#708477">${b?(b.kwh<=goal?'¡Vas dentro de la meta!':'Estás '+num(b.kwh-goal)+' kWh por encima de tu objetivo.'):'Registra un consumo para ver tu avance.'}</p></div></section></div><div class="notice" style="margin-top:14px">El avance usa el último registro disponible, que puede no corresponder al mes objetivo. Mantén tus recibos actualizados para una comparación más representativa.</div>`}
function devicesPage(){return `<div class="content-heading"><div><h2>¿Qué aparatos consumen más?</h2><p>Calcula el consumo aproximado según potencia y horas de uso.</p></div><button class="btn btn-dark" id="addDevice">＋ Añadir aparato</button></div><div class="notice">Estas cifras son aproximaciones: la potencia real, los ciclos de funcionamiento y el modo de uso pueden cambiar el resultado. No son mediciones eléctricas. Para explorar cada aparato por separado, pulsa <b>Analizar</b> en su tarjeta.</div><div class="analysis-launch-card"><div class="analysis-launch-character">🔎</div><div><b>¿Quieres saber qué equipo conviene revisar primero?</b><p>Abre la pantalla de análisis para comparar aparatos, ver un gráfico de consumo mensual y probar escenarios de ahorro.</p></div><button class="btn btn-primary" data-goto="deviceAnalysis">Abrir pantalla de análisis →</button></div><div class="device-grid">${data.devices.map(d=>{const kwh=d.power/1000*d.hours*d.days;return `<article class="device-card"><div class="device-emoji">${d.emoji||'🔌'}</div><h3>${d.name}</h3><p>${d.power} W · ${d.hours} h/día · ${d.days} días</p><strong>${num(kwh)} kWh</strong><small style="display:block;margin-top:4px">≈ ${money(kwh*data.home.tariff)} / mes</small><div style="display:flex;gap:5px;margin-top:14px"><button class="tiny-btn" data-device-analyze="${d.id}">Analizar</button><button class="tiny-btn" data-device-edit="${d.id}">Editar</button><button class="tiny-btn delete" data-device-delete="${d.id}">Eliminar</button></div></article>`}).join('')}</div><section class="panel-card" style="margin-top:15px"><div class="panel-head"><div><h3>Simulador de reducción de uso</h3><p>Explora un escenario de ahorro.</p></div></div><div class="form-grid"><div class="field"><label for="reducePercent">Reducir el uso estimado</label><select id="reducePercent"><option value="5">5 % menos</option><option value="10" selected>10 % menos</option><option value="20">20 % menos</option></select></div><div class="field"><label>Potencial de ahorro mensual</label><div id="deviceSaving" style="font:600 22px 'Space Grotesk';padding:10px 0">${money(data.devices.reduce((s,d)=>s+d.power/1000*d.hours*d.days,0)*data.home.tariff*.1)}</div></div></div><p style="font-size:10px;color:#8b9a8c">Simulación ilustrativa aplicada al consumo calculado de los aparatos registrados.</p></section>`}
function deviceAnalysisPage(){
 const rows=data.devices.map(d=>({...d,kwh:d.power/1000*d.hours*d.days,cost:d.power/1000*d.hours*d.days*data.home.tariff})).sort((a,b)=>b.kwh-a.kwh);
 const total=rows.reduce((s,d)=>s+d.kwh,0),costTotal=rows.reduce((s,d)=>s+d.cost,0),top=rows[0],reduction=10,saving=costTotal*reduction/100;
 const tipFor=d=>d.name.toLowerCase().includes('terma')||d.name.toLowerCase().includes('calent')?'Revisa la temperatura configurada y limita el tiempo de funcionamiento.':d.name.toLowerCase().includes('refri')?'Comprueba el cierre de la puerta, la ventilación y evita abrirla repetidamente.':d.name.toLowerCase().includes('lav')?'Agrupa la ropa y utiliza ciclos adecuados a la carga.':d.name.toLowerCase().includes('tele')||d.name.toLowerCase().includes('pantalla')?'Activa el modo ahorro y apaga el equipo cuando no lo uses.':d.name.toLowerCase().includes('luz')||d.name.toLowerCase().includes('foco')?'Cambia a iluminación LED y aprovecha la luz natural.':'Registra las horas reales de uso y apaga el equipo cuando no sea necesario.';
 return `<section class="analysis-hero"><div><div class="eyebrow">ECOWATT INTELLIGENCE · HOGAR</div><h2>Análisis por electrodoméstico</h2><p>Compara el consumo estimado de cada equipo y decide qué hábito revisar primero. Los resultados se calculan con potencia × horas de uso × días.</p><div class="analysis-hero-tags"><span>⚡ Cálculo estimado</span><span>📊 Comparación visual</span><span>🌱 Ideas de ahorro</span></div></div><div class="analysis-hero-art"><span>🏠</span><span>⚡</span><span>🌿</span></div></section>
 <div class="stats-grid analysis-stats">${stat('Equipos registrados',rows.length,'Aparatos configurados','▦')}${stat('Consumo mensual calculado',num(total)+' <small>kWh</small>','Suma de aparatos','ϟ')}${stat('Costo aproximado',money(costTotal),'Con la tarifa del hogar','S/')}${stat('Ahorro escenario −10%',money(saving),'Si redujeras 10% del uso estimado','✦')}</div>
 <div class="analysis-detail-grid"><section class="panel-card"><div class="panel-head"><div><h3>Comparación de consumo mensual</h3><p>Ordenados del mayor al menor consumo calculado</p></div></div><div class="chart-wrap analysis-main-chart"><canvas id="deviceAnalysisChart"></canvas></div><div class="notice">El consumo calculado no es una lectura del medidor: la potencia nominal y el ciclo real pueden variar.</div></section>
 <section class="panel-card"><div class="panel-head"><div><h3>Tu prioridad sugerida</h3><p>Empieza por el equipo con mayor estimación</p></div><span class="stat-icon">✧</span></div>${top?`<div class="priority-device"><div class="priority-emoji">${top.emoji||'🔌'}</div><div><small>MAYOR CONSUMO CALCULADO</small><h4>${escapeHtml(top.name)}</h4><strong>${num(top.kwh)} kWh/mes</strong><p>≈ ${money(top.cost)} al mes con tu tarifa actual.</p></div></div><div class="recommendation"><div class="rec-icon">💡</div><div><h4>Acción para probar</h4><p>${tipFor(top)}</p></div></div>`:'<div class="empty-state">Añade al menos un aparato para obtener un análisis.</div>'}<button class="btn btn-primary" data-goto="devices">Administrar aparatos →</button></section></div>
 <section class="panel-card analysis-device-list"><div class="panel-head"><div><h3>Ficha de análisis por equipo</h3><p>Consumo, costo aproximado y consejo específico</p></div><button class="tiny-btn" data-goto="report">Incluir en informe ↗</button></div><div class="analysis-device-rows">${rows.map((d,i)=>{const share=total?d.kwh/total*100:0;return `<article class="analysis-device-row"><div class="analysis-device-icon">${d.emoji||'🔌'}</div><div class="analysis-device-main"><div class="analysis-device-title"><b>${escapeHtml(d.name)}</b><span>${num(share)}% del total estimado</span></div><div class="device-share-track"><span style="width:${share}%;--share-color:${['#b8ee63','#61d6e8','#ffc94f','#55d89b','#9a8bff'][i%5]}"></span></div><p>${d.power} W · ${d.hours} h/día · ${d.days} días/mes</p><small>Consejo: ${tipFor(d)}</small></div><div class="analysis-device-values"><b>${num(d.kwh)} kWh</b><span>${money(d.cost)}/mes</span><button class="tiny-btn" data-device-edit="${d.id}">Editar datos</button></div></article>`}).join('')||'<div class="empty-state">No hay aparatos registrados. Añade uno para comenzar.</div>'}</div></section>
 <section class="panel-card scenario-panel"><div class="panel-head"><div><h3>Simula una reducción de uso</h3><p>Explora el ahorro teórico si disminuyes el consumo estimado.</p></div><span class="stat-icon">🌱</span></div><div class="form-grid"><div class="field"><label for="analysisReducePercent">Escenario de reducción</label><select id="analysisReducePercent"><option value="5">5 % menos</option><option value="10" selected>10 % menos</option><option value="15">15 % menos</option><option value="20">20 % menos</option><option value="30">30 % menos</option></select></div><div class="scenario-result"><small>Ahorro mensual orientativo</small><b id="analysisSavingValue">${money(saving)}</b><span id="analysisSavingKwh">${num(total*.1)} kWh menos al mes</span></div></div><p class="report-small-note">La simulación es ilustrativa; el ahorro real depende del uso, los equipos, la tarifa y otros cargos de la factura.</p></section>`;
}
function solarPage(){return `<div class="content-heading"><div><h2>Explora el potencial solar</h2><p>Un escenario inicial para entender qué podría aportar un sistema fotovoltaico.</p></div></div><div class="notice">Este simulador usa supuestos simplificados ingresados por el usuario. No consulta todavía datos solares en tiempo real ni sustituye una evaluación técnica del techo.</div><div class="two-col"><section class="panel-card"><div class="panel-head"><div><h3>Tu escenario solar</h3><p>Ajusta la ubicación y los parámetros del sistema.</p></div></div><form id="solarForm"><div class="field"><label for="solarCity">Ciudad o distrito</label><input id="solarCity" value="${data.home.city||''}" placeholder="Ej. Huaraz, Áncash"></div><div class="form-grid"><div class="field"><label for="solarKw">Potencia instalada (kWp)</label><input type="number" id="solarKw" min=".1" max="100" step=".1" value="${data.home.solarCapacity||2}"></div><div class="field"><label for="solarHsp">Horas solares pico/día (supuesto)</label><input type="number" id="solarHsp" min="1" max="8" step=".1" value="4.5"></div><div class="field"><label for="solarPr">Rendimiento del sistema (%)</label><input type="number" id="solarPr" min="30" max="95" value="78"></div><div class="field"><label for="solarInvestment">Inversión inicial (S/)</label><input type="number" id="solarInvestment" min="0" step="100" value="12000"></div></div><button class="btn btn-dark" type="submit">Calcular escenario →</button></form></section><section class="panel-card"><div class="panel-head"><div><h3>Estimación del escenario</h3><p>Resultados aproximados, no garantizados.</p></div><span class="stat-icon">☀</span></div><div class="map-placeholder"><div class="map-pin"><b>☀</b><span id="solarCityLabel">${data.home.city||'Ubicación no definida'}</span><br><small>Ubicación elegida por ti</small></div></div><div id="solarResults"></div></section></div>`}
function calculateSolar(){const kw=Number($('#solarKw')?.value)||2,hsp=Number($('#solarHsp')?.value)||4.5,pr=(Number($('#solarPr')?.value)||78)/100,investment=Number($('#solarInvestment')?.value)||0,monthly=kw*hsp*30*pr,b=latest(),demand=b?.kwh||0,covered=demand?Math.min(100,monthly/demand*100):0,saving=Math.min(monthly,demand||monthly)*data.home.tariff,annual=saving*12,payback=annual>0?investment/annual:null;$('#solarCityLabel').textContent=$('#solarCity')?.value||'Ubicación no definida';$('#solarResults').innerHTML=`<div class="compare-result"><div><small>GENERACIÓN ESTIMADA</small><b>${num(monthly)} kWh</b></div><div><small>AHORRO POTENCIAL</small><b>${money(saving)}/mes</b></div><div><small>COBERTURA TEÓRICA</small><b>${demand?num(covered)+'%':'—'}</b></div></div><p style="font-size:10px;color:#7d8e80;line-height:1.7;margin-top:14px">Cálculo: potencia × horas solares pico × 30 días × rendimiento. ${payback?`Recuperación simple aproximada: ${num(payback,1)} años, suponiendo que todo el ahorro calculado se materializa.`:'No se puede calcular la recuperación con estos supuestos.'} No incluye sombras, orientación, degradación, mantenimiento, tarifas por bloques ni energía que no puedas autoconsumir.</p>`}
function insightsPage(){const b=latest(),p=previousTo(b),v=p?variation(b.kwh,p.kwh):null;let tips=[];if(v!==null&&v>5)tips.push(['↗','Revisa el aumento reciente',`Tu consumo subió ${num(v)}% frente a ${monthLabel(p.period)}. Comprueba si cambió el tiempo de uso de la terma, la refrigeradora u otros equipos.`]);else if(v!==null&&v< -5)tips.push(['✓','Tu consumo ha disminuido',`Registras una reducción de ${num(Math.abs(v))}% frente al periodo anterior. Identifica qué hábitos pudieron contribuir para mantenerlos.`]);tips.push(['☀','Aprovecha la iluminación natural','Abre cortinas durante el día y apaga las luces en espacios vacíos. Cambia focos incandescentes por LED cuando sea viable.'],['ϟ','Reduce el consumo en espera','Desconecta cargadores y equipos que no necesitan permanecer encendidos; usa regletas con interruptor donde resulte práctico.'],['🚿','Revisa el uso de la terma','Ajusta la temperatura a un nivel seguro y evita mantenerla encendida cuando no se necesita. El impacto depende del equipo y los hábitos.'],['▤','Registra cada recibo','Con más periodos podrás distinguir mejor los cambios y construir proyecciones menos inciertas.']);return `<div class="content-heading"><div><h2>Ideas prácticas para tu hogar</h2><p>Consejos generales y señales sencillas basadas en tu historial.</p></div></div><div class="two-col"><section class="panel-card"><div class="panel-head"><div><h3>Recomendaciones para ti</h3><p>Acciones que puedes probar esta semana.</p></div></div>${tips.map(t=>`<div class="recommendation"><div class="rec-icon">${t[0]}</div><div><h4>${t[1]}</h4><p>${t[2]}</p></div></div>`).join('')}</section><section class="panel-card"><div class="panel-head"><div><h3>Pregúntale a tus datos</h3><p>Respuestas simples usando los registros locales.</p></div></div><div class="field"><label for="questionSelect">¿Qué quieres entender?</label><select id="questionSelect"><option value="increase">¿Por qué aumentó mi consumo?</option><option value="forecast">¿Cuánto podría consumir el próximo mes?</option><option value="save">¿Cómo puedo ahorrar S/ 30 mensuales?</option></select></div><button class="btn btn-dark" id="askData">Analizar mis datos →</button><div id="answerBox" style="margin-top:18px"></div><div class="notice" style="margin-top:18px">Este asistente es una demostración basada en reglas sencillas; no usa una API de IA ni sustituye un análisis profesional.</div></section></div>`}
function settingsPage(){return `<div class="two-col"><section class="panel-card"><div class="panel-head"><div><h3>Configuración del hogar</h3><p>Datos utilizados en las estimaciones.</p></div></div><form id="homeForm"><div class="field"><label for="homeName">Nombre del hogar</label><input id="homeName" required maxlength="60" value="${escapeHtml(data.home.name)}"></div><div class="field"><label for="homeTariff">Tarifa eléctrica (S/ por kWh)</label><input id="homeTariff" type="number" min="0" step=".001" required value="${data.home.tariff}"></div><div class="field"><label for="homeCity">Ciudad o distrito (opcional)</label><input id="homeCity" value="${escapeHtml(data.home.city||'')}" placeholder="Ej. Huaraz, Áncash"></div><button class="btn btn-dark" type="submit">Guardar configuración</button></form></section><section class="panel-card"><div class="panel-head"><div><h3>Datos y privacidad</h3><p>Controla la información de esta demostración.</p></div></div><div class="recommendation"><div class="rec-icon">⌂</div><div><h4>Almacenamiento local</h4><p>Los datos de esta versión se guardan en localStorage de este navegador. No se sincronizan entre dispositivos.</p></div></div><div class="recommendation"><div class="rec-icon">⇩</div><div><h4>Exporta tu información</h4><p>Descarga los registros de consumo en formato CSV para conservar una copia.</p><button class="tiny-btn" id="exportSettingsCsv" style="margin-top:8px">Exportar registros</button></div></div><div class="recommendation"><div class="rec-icon">↺</div><div><h4>Restablecer demostración</h4><p>Recupera los datos de ejemplo. Esta acción reemplazará tus registros actuales de este navegador.</p><button class="tiny-btn delete" id="resetDemo" style="margin-top:8px">Restablecer datos</button></div></div></section></div>`}
function locationPage(){return `<div class="content-heading"><div><h2>Ubicación y análisis territorial</h2><p>Usa tu ubicación actual para contextualizar el análisis energético de tu hogar.</p></div><span class="live-badge"><i></i> GPS / navegador</span></div><div class="notice">Tu ubicación solo se consulta cuando pulsas un botón y autorizas el navegador. Para recibir coordenadas precisas, abre esta web en localhost o mediante HTTPS. La ubicación por sí sola no mide el consumo eléctrico.</div><div class="location-layout"><section class="panel-card location-controls"><div class="panel-head"><div><h3>📍 Ubicación y parcela</h3><p>Obtén tu ubicación y actualízala mientras te mueves.</p></div></div><div class="location-actions"><button class="btn btn-primary" id="locateOnce">📍 Obtener ubicación</button><button class="btn btn-dark" id="startTracking">◉ Seguimiento en vivo</button><button class="btn btn-light" id="stopTracking">■ Detener</button></div><div class="location-status" id="locationStatus" role="status">Esperando tu autorización. No se ha solicitado la ubicación.</div><div class="location-metrics"><div><small>Latitud</small><b id="locLat">—</b></div><div><small>Longitud</small><b id="locLng">—</b></div><div><small>Precisión</small><b id="locAccuracy">—</b></div><div><small>Última actualización</small><b id="locUpdated">—</b></div></div><div class="field" style="margin-top:18px"><label for="locationCity">Ciudad o distrito (alternativa manual)</label><input id="locationCity" value="${(data.home.city||'').replace(/"/g,'&quot;')}" placeholder="Ej. Huaraz, Áncash"></div><button class="btn btn-light" id="saveLocationCity">Guardar ciudad</button><p class="location-privacy">🔒 No compartimos ni enviamos tus coordenadas a un servidor en esta demo. Puedes detener el seguimiento en cualquier momento.</p></section><section class="panel-card"><div class="panel-head"><div><h3>Mapa de tu ubicación</h3><p>El marcador se mueve cuando el navegador entrega nuevas coordenadas.</p></div><span class="map-source">OpenStreetMap</span></div><div id="liveMap" class="live-map" aria-label="Mapa de ubicación"></div><p class="map-footnote">El mapa necesita conexión a internet para cargar los mosaicos. Si no autorizas la ubicación, puedes seguir usando la ciudad configurada.</p></section></div><section class="panel-card location-analysis"><div class="panel-head"><div><h3>Lectura energética de la zona</h3><p>Resumen orientativo basado en tus registros y la ubicación disponible.</p></div><span class="stat-icon">✦</span></div><div class="location-analysis-grid"><div class="analysis-tile"><small>Hogar configurado</small><b>${data.home.name||'Mi hogar'}</b><span>${data.home.city||'Ciudad no configurada'}</span></div><div class="analysis-tile"><small>Consumo más reciente</small><b>${latest()?num(latest().kwh)+' kWh':'Sin registros'}</b><span>${latest()?monthLabel(latest().period):'Agrega un recibo para analizar'}</span></div><div class="analysis-tile"><small>Costo energético estimado</small><b>${latest()?money(latest().kwh*data.home.tariff):'—'}</b><span>Consumo × tarifa configurada</span></div><div class="analysis-tile"><small>Próximo paso recomendado</small><b>Evalúa tu potencial solar</b><span>La ubicación no sustituye datos de radiación validados.</span><button class="tiny-btn" data-goto="solar">Abrir GeoSolar ↗</button></div></div></section>`}
function initLocationPage(){
 const status=$('#locationStatus');
 if(window.L&&$('#liveMap')){if(liveMap){liveMap.remove();liveMap=null}const start=lastPosition?[lastPosition.lat,lastPosition.lng]:[-9.5278,-77.5278];liveMap=L.map('liveMap').setView(start,lastPosition?15:12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(liveMap);if(lastPosition){liveMarker=L.marker(start).addTo(liveMap).bindPopup('Tu ubicación actual').openPopup()}setTimeout(()=>liveMap&&liveMap.invalidateSize(),150)}else if(status){status.textContent='No se pudo cargar el mapa. Comprueba tu conexión a internet.'}
 $('#locateOnce')?.addEventListener('click',()=>requestLocation(false));$('#startTracking')?.addEventListener('click',()=>requestLocation(true));$('#stopTracking')?.addEventListener('click',stopLocationTracking);
 $('#saveLocationCity')?.addEventListener('click',()=>{const city=$('#locationCity').value.trim();if(!city){toast('Escribe una ciudad o distrito.');return}data.home.city=city;saveData();toast('Ciudad guardada para el análisis.');renderPage('location')});
 if(lastPosition)updateLocationUI(lastPosition);if(locationWatchId!==null)status.textContent='Seguimiento en vivo activado. Mantén esta página abierta.';
}
function requestLocation(track){const status=$('#locationStatus');if(!navigator.geolocation){status.textContent='Este navegador no ofrece geolocalización. Ingresa la ciudad manualmente.';return}if(!window.isSecureContext){status.textContent='La ubicación requiere HTTPS o localhost. Abre el proyecto con Live Server en VS Code.';toast('Usa Live Server o una web con HTTPS.');return}status.textContent='Solicitando permiso al navegador…';const success=pos=>{lastPosition={lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy,time:new Date(pos.timestamp)};updateLocationUI(lastPosition);if(liveMap){const ll=[lastPosition.lat,lastPosition.lng];liveMap.setView(ll,Math.max(liveMap.getZoom(),15));if(!liveMarker)liveMarker=L.marker(ll).addTo(liveMap);else liveMarker.setLatLng(ll);liveMarker.bindPopup('Ubicación actual · precisión aproximada '+Math.round(lastPosition.accuracy)+' m').openPopup()}status.textContent=(track?'Seguimiento activo. ':'Ubicación obtenida. ')+'Precisión aproximada: '+Math.round(lastPosition.accuracy)+' m.'};const error=err=>{const messages={1:'Permiso denegado. Activa la ubicación para este sitio desde los ajustes del navegador.',2:'No se pudo determinar la ubicación. Activa GPS/Wi-Fi o prueba al aire libre.',3:'La solicitud tardó demasiado. Vuelve a intentarlo.'};status.textContent=messages[err.code]||'No fue posible obtener la ubicación.'};if(track){if(locationWatchId!==null)navigator.geolocation.clearWatch(locationWatchId);locationWatchId=navigator.geolocation.watchPosition(success,error,{enableHighAccuracy:true,maximumAge:5000,timeout:20000});status.textContent='Solicitando ubicación y activando seguimiento…'}else navigator.geolocation.getCurrentPosition(success,error,{enableHighAccuracy:true,maximumAge:0,timeout:20000})}
function updateLocationUI(pos){if($('#locLat'))$('#locLat').textContent=pos.lat.toFixed(6);if($('#locLng'))$('#locLng').textContent=pos.lng.toFixed(6);if($('#locAccuracy'))$('#locAccuracy').textContent=Math.round(pos.accuracy)+' m';if($('#locUpdated'))$('#locUpdated').textContent=pos.time.toLocaleTimeString('es-PE');}
function stopLocationTracking(){if(locationWatchId!==null){navigator.geolocation.clearWatch(locationWatchId);locationWatchId=null}const s=$('#locationStatus');if(s)s.textContent='Seguimiento detenido. La última ubicación obtenida sigue visible hasta que salgas de la página.';toast('Seguimiento de ubicación detenido.')}
function helpPage(){return `<div class="content-heading"><div><h2>Ayuda y privacidad</h2><p>Información clara sobre cómo funciona EcoWatt.</p></div></div><div class="two-col"><section class="panel-card"><div class="panel-head"><div><h3>Preguntas frecuentes</h3></div></div>${[['¿Qué datos debo ingresar?','El periodo de facturación y el consumo en kWh que aparece en tu recibo. El importe total es opcional y permite conservar una referencia del total facturado.'],['¿Cómo se calcula el costo estimado?','EcoWatt multiplica el consumo en kWh por la tarifa S/ por kWh configurada. Es una aproximación y puede diferir del total del recibo por cargos, impuestos, bloques tarifarios u otros conceptos.'],['¿Las predicciones son exactas?','No. Esta demo no utiliza un modelo predictivo entrenado. Cualquier proyección debe considerarse orientativa y evaluarse con suficiente historial real.'],['¿Puedo subir una foto del recibo?','Sí. El escáner intenta reconocer texto en la imagen desde el navegador. Debes verificar manualmente el periodo, los kWh y el importe antes de guardar; el OCR puede equivocarse. El código EW- es un identificador interno generado por EcoWatt, no el código oficial de la empresa eléctrica.']].map(x=>`<details style="border-bottom:1px solid #e9eee7;padding:15px 0"><summary style="font-size:12px;font-weight:700;cursor:pointer">${x[0]}</summary><p style="font-size:11px;color:#819184;line-height:1.8">${x[1]}</p></details>`).join('')}</section><section class="panel-card"><div class="panel-head"><div><h3>Privacidad y límites</h3></div></div><div class="recommendation"><div class="rec-icon">⌑</div><div><h4>En esta versión</h4><p>Los datos se guardan en el almacenamiento local del navegador. Borrar los datos del sitio puede eliminarlos. No introduzcas información sensible en una demo.</p></div></div><div class="recommendation"><div class="rec-icon">⚿</div><div><h4>Antes de publicar</h4><p>Una versión pública necesita autenticación real, base de datos, políticas de acceso por usuario, HTTPS, gestión segura de secretos, copias de respaldo y una política de privacidad.</p></div></div><div class="recommendation"><div class="rec-icon">☀</div><div><h4>Resultados solares</h4><p>La estimación solar simplificada no reemplaza datos de radiación verificados ni una evaluación de sombras, orientación, inclinación y condiciones de instalación.</p></div></div></section></div>`}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function chartOptions(){return {responsive:true,maintainAspectRatio:false,animation:{duration:850,easing:'easeOutQuart'},interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{backgroundColor:'#123a2c',titleColor:'#f5ffe9',bodyColor:'#e6f8d9',padding:13,cornerRadius:12,displayColors:true}},scales:{x:{grid:{display:false},ticks:{color:'#a4cbb7',font:{size:12,weight:'600'}},border:{display:false}},y:{beginAtZero:true,grid:{color:'#28523f',lineWidth:1.2},ticks:{color:'#a4cbb7',font:{size:11}},border:{display:false}}}}}
function drawDashboardCharts(){const arr=sortedBills();const ctx=$('#dashboardChart');if(ctx&&window.Chart){const g=ctx.getContext('2d').createLinearGradient(0,0,0,280);g.addColorStop(0,'rgba(65,190,115,.38)');g.addColorStop(1,'rgba(65,190,115,.02)');charts.dashboard=new Chart(ctx,{type:'line',data:{labels:arr.map(b=>monthLabel(b.period)),datasets:[{label:'Consumo (kWh)',data:arr.map(b=>b.kwh),borderColor:'#19a968',backgroundColor:g,fill:true,tension:.38,borderWidth:4,pointRadius:6,pointHoverRadius:9,pointBackgroundColor:'#d7f36d',pointBorderColor:'#138753',pointBorderWidth:2,yAxisID:'y'},{label:'Costo estimado (S/)',data:arr.map(b=>b.kwh*data.home.tariff),borderColor:'#f0b52e',backgroundColor:'rgba(240,181,46,.10)',fill:false,tension:.35,borderWidth:3,pointRadius:5,pointHoverRadius:8,pointBackgroundColor:'#fff0a4',pointBorderColor:'#d99a10',pointBorderWidth:2,borderDash:[7,4],yAxisID:'y1'}]},options:{...chartOptions(),scales:{...chartOptions().scales,y:{...chartOptions().scales.y,title:{display:true,text:'Consumo · kWh',color:'#a4cbb7',font:{weight:'700',size:12}},ticks:{...chartOptions().scales.y.ticks,precision:0}},y1:{position:'right',grid:{display:false},ticks:{color:'#ffd25d',font:{size:11,weight:'600'}},title:{display:true,text:'Costo · S/',color:'#ffd25d',font:{weight:'700',size:12}},border:{display:false}}}}})}
 const dc=$('#dashboardDeviceChart');if(dc&&window.Chart){const devs=data.devices.map(d=>({name:d.name,kwh:d.power/1000*d.hours*d.days})).sort((a,b)=>b.kwh-a.kwh);charts.dashboardDevices=new Chart(dc,{type:'doughnut',data:{labels:devs.map(d=>d.name),datasets:[{data:devs.map(d=>d.kwh),backgroundColor:['#b8ee63','#61d6e8','#ffc94f','#55d89b','#9a8bff','#ff8f70'],borderColor:'#103629',borderWidth:4,hoverOffset:10}]},options:{...chartOptions(),cutout:'62%',plugins:{...chartOptions().plugins,legend:{position:'bottom',labels:{color:'#c9e6d3',padding:14,usePointStyle:true,pointStyle:'circle'}}}}})}}
function drawDeviceAnalysisChart(){const c=$('#deviceAnalysisChart');if(!c||!window.Chart)return;const rows=data.devices.map(d=>({name:d.name,kwh:d.power/1000*d.hours*d.days})).sort((a,b)=>b.kwh-a.kwh);charts.deviceAnalysis=new Chart(c,{type:'bar',data:{labels:rows.map(d=>d.name),datasets:[{label:'Consumo estimado (kWh/mes)',data:rows.map(d=>d.kwh),backgroundColor:rows.map((_,i)=>['#b8ee63','#61d6e8','#ffc94f','#55d89b','#9a8bff'][i%5]),borderColor:rows.map((_,i)=>['#7ebc3b','#269eae','#d39b19','#249e6c','#7161cc'][i%5]),borderWidth:2,borderRadius:9,borderSkipped:false}]},options:{...chartOptions(),indexAxis:'y',plugins:{...chartOptions().plugins,legend:{display:false}},scales:{x:{beginAtZero:true,grid:{color:'rgba(170,220,190,.12)'},ticks:{color:'#a8cbb6'},title:{display:true,text:'kWh por mes',color:'#d5f36b'}},y:{grid:{display:false},ticks:{color:'#e8f7e8',font:{weight:'600'}},border:{display:false}}}}})}
function drawHistoryCharts(){const arr=sortedBills();if(!window.Chart)return;const opt=chartOptions();const c=$('#historyConsumption');if(c)charts.hc=new Chart(c,{type:'bar',data:{labels:arr.map(b=>monthLabel(b.period)),datasets:[{label:'Consumo (kWh)',data:arr.map(b=>b.kwh),backgroundColor:arr.map((_,i)=>i===arr.length-1?'#19a968':i%2?'#72c9df':'#a8df72'),borderColor:arr.map((_,i)=>i===arr.length-1?'#087b48':i%2?'#278da8':'#5eae42'),borderWidth:2,borderRadius:10,borderSkipped:false,maxBarThickness:54,hoverBackgroundColor:'#d5ef69'}]},options:opt});const c2=$('#historyCost');if(c2)charts.hcost=new Chart(c2,{type:'line',data:{labels:arr.map(b=>monthLabel(b.period)),datasets:[{label:'Gasto estimado (S/)',data:arr.map(b=>b.kwh*data.home.tariff),borderColor:'#edb52f',backgroundColor:'rgba(237,181,47,.22)',fill:true,tension:.38,borderWidth:4,pointRadius:6,pointHoverRadius:9,pointBackgroundColor:'#aee8f3',pointBorderColor:'#178fa5',pointBorderWidth:2}]},options:opt})}
function downloadCsv(){const rows=[['periodo','consumo_kwh','costo_estimado_pen','importe_recibo_pen','origen'],...sortedBills().map(b=>[b.period,b.kwh,(b.kwh*data.home.tariff).toFixed(2),b.amount??'',b.source||''])];const csv='\uFEFF'+rows.map(r=>r.map(x=>`"${String(x).replace(/"/g,'""')}"`).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ecowatt-registros.csv';a.click();URL.revokeObjectURL(url);toast('Archivo CSV preparado.')}
function bindPageEvents(){
 $$('[data-goto]').forEach(b=>b.addEventListener('click',()=>renderPage(b.dataset.goto)));
 $('#newBillBtn')?.addEventListener('click',()=>{editingId=null;renderPage('bills');$('#billPeriod').focus()});
 $('#cancelEdit')?.addEventListener('click',()=>{editingId=null;renderPage('bills')});
 $('#billForm')?.addEventListener('submit',e=>{e.preventDefault();const period=$('#billPeriod').value,kwh=Number($('#billKwh').value),amount=$('#billAmount').value===''?null:Number($('#billAmount').value);if(!period||kwh<0||!Number.isFinite(kwh)){toast('Revisa los datos ingresados.');return}if(data.bills.some(b=>b.period===period&&b.id!==editingId)){if(!confirm('Ya existe un registro para este periodo. ¿Deseas guardar otro?'))return}if(editingId){const old=data.bills.find(b=>b.id===editingId);Object.assign(old,{period,kwh,amount,source:$('#billSource').value})}else data.bills.push({id:Date.now(),period,kwh,amount,source:$('#billSource').value});editingId=null;saveData();toast('Registro guardado correctamente.');renderPage('bills')});
 $$('[data-edit]').forEach(b=>b.addEventListener('click',()=>{editingId=Number(b.dataset.edit);renderPage('bills');$('#billFormTitle').textContent='Editar registro';$('#billForm').scrollIntoView({behavior:'smooth',block:'center'})}));
 $$('[data-delete]').forEach(b=>b.addEventListener('click',()=>{const id=Number(b.dataset.delete);if(confirm('¿Eliminar este registro de consumo?')){data.bills=data.bills.filter(x=>x.id!==id);saveData();renderPage('bills');toast('Registro eliminado.')}}));
 $('#exportCsv')?.addEventListener('click',downloadCsv);$('#exportSettingsCsv')?.addEventListener('click',downloadCsv);
 $('#compareA')?.addEventListener('change',updateCompare);$('#compareB')?.addEventListener('change',updateCompare);
 $('#goalForm')?.addEventListener('submit',e=>{e.preventDefault();data.goal={kwh:Number($('#goalKwh').value),period:$('#goalPeriod').value};saveData();toast('Meta actualizada.');renderPage('goals')});
 $('#homeForm')?.addEventListener('submit',e=>{e.preventDefault();data.home.name=$('#homeName').value.trim();data.home.tariff=Number($('#homeTariff').value);data.home.city=$('#homeCity').value.trim();saveData();$('#sideHomeName').textContent=data.home.name;toast('Configuración guardada.');renderPage('settings')});
 $('#solarForm')?.addEventListener('submit',e=>{e.preventDefault();data.home.city=$('#solarCity').value;data.home.solarCapacity=Number($('#solarKw').value);saveData();calculateSolar();toast('Escenario calculado.');});if(currentPage==='solar')calculateSolar();
 $('#reducePercent')?.addEventListener('change',()=>{const pct=Number($('#reducePercent').value)/100;$('#deviceSaving').textContent=money(data.devices.reduce((s,d)=>s+d.power/1000*d.hours*d.days,0)*data.home.tariff*pct)});
 $('#analysisReducePercent')?.addEventListener('change',()=>{const pct=Number($('#analysisReducePercent').value)/100,total=data.devices.reduce((s,d)=>s+d.power/1000*d.hours*d.days,0);if($('#analysisSavingValue'))$('#analysisSavingValue').textContent=money(total*data.home.tariff*pct);if($('#analysisSavingKwh'))$('#analysisSavingKwh').textContent=`${num(total*pct)} kWh menos al mes`});
 $$('[data-device-analyze]').forEach(b=>b.addEventListener('click',()=>{renderPage('deviceAnalysis');const target=data.devices.find(d=>d.id===Number(b.dataset.deviceAnalyze));if(target)toast(`Análisis de ${target.name}: revisa su ficha y su participación en el gráfico.`)}));
 $('#askData')?.addEventListener('click',answerQuestion);
 $('#addDevice')?.addEventListener('click',()=>{const name=prompt('Nombre del electrodoméstico:');if(!name?.trim())return;const power=Number(prompt('Potencia nominal en watts (W):','100'));const hours=Number(prompt('Horas de uso por día:','2'));const days=Number(prompt('Días de uso por mes:','30'));if(!(power>0&&hours>=0&&days>=0)){toast('Ingresa valores válidos.');return}data.devices.push({id:Date.now(),name:name.trim(),emoji:'🔌',power,hours,days});saveData();renderPage('devices');toast('Electrodoméstico agregado.')});
 $$('[data-device-delete]').forEach(b=>b.addEventListener('click',()=>{if(confirm('¿Eliminar este aparato?')){data.devices=data.devices.filter(d=>d.id!==Number(b.dataset.deviceDelete));saveData();renderPage('devices')}}));
 $$('[data-device-edit]').forEach(b=>b.addEventListener('click',()=>{const d=data.devices.find(d=>d.id===Number(b.dataset.deviceEdit));if(!d)return;const name=prompt('Nombre',d.name);if(name===null)return;const power=Number(prompt('Potencia (W)',d.power)),hours=Number(prompt('Horas por día',d.hours)),days=Number(prompt('Días por mes',d.days));if(name.trim()&&power>0&&hours>=0&&days>=0){Object.assign(d,{name:name.trim(),power,hours,days});saveData();renderPage('devices')}}));
 $('#resetDemo')?.addEventListener('click',()=>{if(confirm('Esto reemplazará los datos actuales por los ejemplos. ¿Continuar?')){data=defaultData();saveData();toast('Datos de ejemplo restaurados.');renderPage('settings')}});
 $('#receiptFile')?.addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Selecciona una imagen JPG, PNG o similar.');return}const imgUrl=URL.createObjectURL(file);$('#scanPreview').src=imgUrl;$('#scanPreviewWrap').classList.remove('hidden');const code=generateReceiptCode();$('#scanFileMeta').textContent=`${file.name} · ${Math.round(file.size/1024)} KB · Código: ${code}`;$('#runOcr').disabled=false;$('#scanStatus').textContent='Imagen lista. Ejecuta la lectura automática cuando quieras.';$('#receiptCodeDisplay').textContent=code;$('#receiptCodeDisplay').dataset.code=code;});
 $('#runOcr')?.addEventListener('click',()=>runReceiptOcr($('#receiptFile')?.files?.[0]));
 $('#scanReviewForm')?.addEventListener('submit',e=>{e.preventDefault();const period=$('#scanPeriod').value,kwh=Number($('#scanKwh').value),amount=$('#scanAmount').value===''?null:Number($('#scanAmount').value);if(!period||!Number.isFinite(kwh)||kwh<0){toast('Revisa el periodo y los kWh.');return}if(data.bills.some(x=>x.period===period)&&!confirm('Ya existe un recibo para este periodo. ¿Guardar de todas formas?'))return;const code=$('#receiptCodeDisplay').dataset.code||generateReceiptCode();data.bills.push({id:Date.now(),period,kwh,amount,source:'Escáner OCR · '+code,receiptCode:code,supplyCode:$('#scanSupplyCode').value.trim()});saveData();toast('Consumo guardado. Código '+code);renderPage('report')});
 $('#scanClear')?.addEventListener('click',()=>{if($('#scanReviewForm'))$('#scanReviewForm').reset();$('#scanPeriod').value=currentMonth();$('#scanOcrText').value='';$('#scanPreviewWrap').classList.add('hidden');$('#receiptFile').value='';$('#runOcr').disabled=true;$('#receiptCodeDisplay').textContent='Código pendiente';$('#receiptCodeDisplay').dataset.code='';$('#scanStatus').textContent='Selecciona una imagen para empezar.'});
 $('#downloadPdfPage')?.addEventListener('click',downloadPdfReport);
 if(currentPage==='report'&&window.Chart){const c=$('#reportChart'),arr=sortedBills();if(c)charts.report=new Chart(c,{type:'bar',data:{labels:arr.map(x=>monthLabel(x.period)),datasets:[{label:'Consumo kWh',data:arr.map(x=>x.kwh),backgroundColor:arr.map((_,i)=>i===arr.length-1?'#d5f36a':i%2?'#68d2e7':'#43c987'),borderColor:arr.map((_,i)=>i===arr.length-1?'#89b63a':i%2?'#2399ad':'#1a9a66'),borderWidth:2,borderRadius:10,borderSkipped:false}]},options:chartOptions()})}
}
function updateCompare(){const a=data.bills.find(x=>x.id===Number($('#compareA').value)),b=data.bills.find(x=>x.id===Number($('#compareB').value));$('#compareResults').innerHTML=compareResult(a,b)}
function answerQuestion(){const b=latest(),p=previousTo(b),v=p?variation(b.kwh,p.kwh):null,q=$('#questionSelect').value;let title,body;if(q==='increase'){title='Lectura de tu historial';body=!b||!p?'Aún necesitas al menos dos periodos registrados para detectar un cambio.':v>0?`El último periodo subió ${num(v)}% (${num(b.kwh-p.kwh)} kWh) respecto a ${monthLabel(p.period)}. El registro no permite identificar por sí solo la causa: revisa cambios de clima, uso de terma, visitas o nuevos equipos.`:v<0?`El último periodo bajó ${num(Math.abs(v))}% frente a ${monthLabel(p.period)}. Revisa qué hábitos cambiaron y si se mantienen.`:'El consumo registrado es igual al del periodo anterior.'}else if(q==='forecast'){const avg=data.bills.length?data.bills.reduce((s,x)=>s+x.kwh,0)/data.bills.length:0;title='Proyección orientativa';body=data.bills.length<3?'Registra al menos tres periodos para que una proyección básica tenga una referencia mínima.':`El promedio simple de tus ${data.bills.length} registros es ${num(avg)} kWh por periodo, equivalente a ${money(avg*data.home.tariff)} con tu tarifa actual. No es una predicción validada y no contempla estacionalidad.`}else{const target=30,tariff=Number(data.home.tariff);title='Escenario para ahorrar S/ 30';body=tariff>0?`Para reducir S/ 30 en costo energético a tu tarifa actual, tendrías que reducir aproximadamente ${num(target/tariff)} kWh al mes. Empieza revisando la terma y los equipos de mayor potencia; las cifras reales dependen del uso y de la tarifa de tu recibo.`:'Configura una tarifa mayor que cero para calcular los kWh aproximados que equivalen a S/ 30.'}$('#answerBox').innerHTML=`<div class="recommendation"><div class="rec-icon">✧</div><div><h4>${title}</h4><p>${body}</p></div></div>`}
$('#todayChip').textContent='● '+new Date().toLocaleDateString('es-PE',{weekday:'short',day:'2-digit',month:'short'});
$('#exploreDemo').addEventListener('click',()=>enterApp('demo@ecowatt.pe'));
$$('[data-auth]').forEach(b=>b.addEventListener('click',()=>openAuth(b.dataset.auth)));
function openAuth(mode){authMode=mode;const recovery=mode==='recover';$('#authTitle').textContent=mode==='register'?'Crea tu cuenta':recovery?'Recupera tu acceso':'Bienvenido de nuevo';$('#authDescription').textContent=mode==='register'?'Empieza a entender la energía de tu hogar.':recovery?'Escribe tu correo para iniciar el flujo de recuperación.':'Ingresa para consultar la energía de tu hogar.';$('#authPassword').closest('label').classList.toggle('hidden',recovery);$('#authPassword').required=!recovery;$('#authSubmit').textContent=mode==='register'?'Crear cuenta →':recovery?'Enviar instrucciones →':'Ingresar →';$('#authSwitch').classList.toggle('hidden',recovery);$('#forgotPassword').classList.toggle('hidden',recovery||mode==='register');$('#authSwitch').textContent=mode==='register'?'¿Ya tienes cuenta? Ingresar':'¿No tienes cuenta? Crear una';$('#authModal').classList.remove('hidden')}
$('#closeAuth').addEventListener('click',()=>$('#authModal').classList.add('hidden'));
$('#authSwitch').addEventListener('click',()=>openAuth(authMode==='register'?'login':'register'));
$('#forgotPassword').addEventListener('click',()=>openAuth('recover'));
$('#authForm').addEventListener('submit',e=>{e.preventDefault();const email=$('#authEmail').value.trim(),pass=$('#authPassword').value;if(authMode==='recover'){if(!email){toast('Ingresa tu correo electrónico.');return}$('#authModal').classList.add('hidden');toast('Flujo de recuperación simulado. Para enviar correos reales hace falta configurar un servidor de autenticación.');return}if(pass.length<6){toast('La contraseña debe tener al menos 6 caracteres.');return}$('#authModal').classList.add('hidden');enterApp(email);toast(authMode==='register'?'Espacio de demostración creado. La cuenta segura requiere un servidor.':'Sesión de demostración iniciada.')});
$('#logoutBtn').addEventListener('click',leaveApp);
$('#downloadPdfTop')?.addEventListener('click',downloadPdfReport);
$('#addBillTop').addEventListener('click',()=>renderPage('bills'));
$$('.side-link[data-page]').forEach(b=>b.addEventListener('click',()=>renderPage(b.dataset.page)));
$('#mobileMenu').addEventListener('click',()=>{$('.landing-nav').classList.toggle('menu-open')});
