const buddyMessages=[ '¡Hola! Soy Eco ⚡. Registra tu recibo y te ayudo a entender los cambios.', 'Un aumento en kWh no explica por sí solo la causa. Compara hábitos, clima y equipos.', '¿Quieres ahorrar? Revisa primero los aparatos de mayor potencia y las horas de uso.', 'Con tu permiso, puedo mostrar la ubicación de tu dispositivo; no mide el consumo eléctrico.'];
let buddyIndex=0;
$('#buddyToggle')?.addEventListener('click',()=>{$('#buddyChat').classList.toggle('open');$('#buddyToggle').classList.add('buddy-hello');setTimeout(()=>$('#buddyToggle')?.classList.remove('buddy-hello'),700)});
$('#buddyClose')?.addEventListener('click',()=>$('#buddyChat').classList.remove('open'));
$('#buddyAsk')?.addEventListener('click',()=>{const b=latest(),p=previousTo(b);let msg=b&&p?`Tu último consumo fue ${num(b.kwh)} kWh. Frente al periodo anterior, la diferencia es ${num(b.kwh-p.kwh)} kWh. El costo energético estimado es ${money(b.kwh*data.home.tariff)}. Es una lectura de tus registros, no un diagnóstico de la causa.`:'Registra al menos dos periodos de consumo para que pueda comparar cambios. También puedes abrir Ubicación en vivo para contextualizar tu análisis.';$('#buddyMessage').textContent=msg;$('#buddyChat').classList.add('open')});
$('#buddyScan')?.addEventListener('click',()=>{renderPage('scanner');$('#ecoBuddy').classList.remove('open')});
